declare const brandedEnumTag: unique symbol;

export type BrandedEnum = string & { readonly [brandedEnumTag]: true };

declare const brandedIdTag: unique symbol;

export type BrandedId = string & { readonly [brandedIdTag]: true };

export type BoundedValue = number | boolean | BrandedEnum | BrandedId;

export type BoundedPayload = { readonly [key: string]: BoundedValue | undefined };

export function brandedEnumOf(
	values: readonly string[],
	fallback: string,
): (value: string | undefined) => BrandedEnum | undefined {
	const admitted = new Set(values);
	return (value) => {
		if (value === undefined) return undefined;
		return (admitted.has(value) ? value : fallback) as BrandedEnum;
	};
}

export function brandLiteralEnum<T extends string>(
	value: string extends T ? never : T,
): BrandedEnum {
	return value as unknown as BrandedEnum;
}

const OPAQUE_ID = /^[0-9A-Za-z._:|-]{1,128}$/;

export function brandedId(value: string | undefined): BrandedId | undefined {
	return value !== undefined && OPAQUE_ID.test(value) ? (value as BrandedId) : undefined;
}

