import { copyFileSync, existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";

import { brandedErrno, type BrandedEnum } from "../../../shared/errors/bounded.js";
import { findSystemErrno } from "../../../shared/system-errno.js";
import {
	isSqliteBusyError,
	isSqliteCantOpenError,
	isSqliteCorruptError,
	isSqliteIoError,
} from "../../storage/sqlite-busy.js";
import { DB_BUSY_TIMEOUT_MS, SQLITE_DB_SIDECAR_SUFFIXES } from "../../storage/store-db.js";

// Writes a transactionally-consistent copy of a live SQLite db to `destPath`
// without disturbing the writer. The source is opened READ-ONLY and VACUUM INTO
// snapshots it inside a read transaction, so a process holding the db open (e.g.
// Chrome on its cookie/login dbs) is never stopped, signaled, or locked out —
// the copy is a self-contained file with no -wal/-shm/-journal sidecar to pair.
// `destPath` must not already exist (SQLite refuses a non-empty target).
// `busyTimeoutMs` caps how long the read lock is waited for; a short value lets a
// caller fail fast to a fallback when a db is held with a long-lived lock.
export function sqliteVacuumInto(
	srcPath: string,
	destPath: string,
	busyTimeoutMs: number = DB_BUSY_TIMEOUT_MS,
): void {
	const db = new DatabaseSync(srcPath, { readOnly: true });
	try {
		db.exec(`PRAGMA busy_timeout = ${busyTimeoutMs}`);
		db.exec(`VACUUM INTO '${destPath.replace(/'/g, "''")}'`);
	} finally {
		db.close();
	}
}

// Bounded attempts at the byte-stable snapshot copyLockedSqliteDb accepts.
const LOCKED_DB_COPY_ATTEMPTS = 3;

export type SqliteSnapshotFailureOperation =
	| "vacuum_into"
	| "prepare_staged"
	| "read_source_main"
	| "write_staged_main"
	| "copy_source_sidecars"
	| "verify_source_stability"
	| "open_staged"
	| "checkpoint_staged"
	| "set_staged_journal_mode"
	| "quick_check_staged"
	| "close_staged"
	| "cleanup_staged";
export type SqliteSnapshotPathStage =
	| "source_main"
	| "source_sidecars"
	| "staged_main"
	| "staged_sidecars"
	| "source_and_staged_sidecars"
	| "source_or_staged_main";
export type SqliteSnapshotFailureCause =
	| "busy"
	| "io"
	| "corrupt"
	| "cant_open"
	| "sqlite"
	| "system"
	| "source_changed"
	| "quick_check_failed"
	| "error"
	| "unknown";
export type SqliteSnapshotErrorClass = "Error" | "TypeError" | "RangeError" | "none" | "unknown";

export interface SqliteSnapshotFailure {
	readonly operation: SqliteSnapshotFailureOperation;
	readonly pathStage: SqliteSnapshotPathStage;
	readonly cause: SqliteSnapshotFailureCause;
	readonly errorClass: SqliteSnapshotErrorClass;
	readonly errno?: BrandedEnum;
	readonly sqliteCode?: number;
}

export function classifySqliteSnapshotFailure(
	error: unknown,
	operation: SqliteSnapshotFailureOperation,
	pathStage: SqliteSnapshotPathStage,
): SqliteSnapshotFailure {
	const candidate = (error as { readonly errcode?: unknown } | null)?.errcode;
	const sqliteCode =
		typeof candidate === "number" && Number.isSafeInteger(candidate) && candidate >= 0
			? candidate
			: undefined;
	const systemErrno = sqliteCode === undefined ? findSystemErrno(error) : undefined;
	const errno = brandedErrno(systemErrno);
	const primarySqliteCode = sqliteCode === undefined ? undefined : sqliteCode & 0xff;
	const isCapacityFailure =
		systemErrno === "ENOSPC" || systemErrno === "EDQUOT" || primarySqliteCode === 13;
	let resolvedPathStage = pathStage;
	if (operation === "vacuum_into" && isCapacityFailure) {
		resolvedPathStage = "staged_main";
	} else if (operation === "copy_source_sidecars" && isCapacityFailure) {
		resolvedPathStage = "staged_sidecars";
	} else if (
		operation === "vacuum_into" &&
		(isSqliteBusyError(error) || isSqliteCorruptError(error))
	) {
		resolvedPathStage = "source_main";
	}
	let errorClass: SqliteSnapshotErrorClass = "unknown";
	if (error instanceof TypeError) errorClass = "TypeError";
	else if (error instanceof RangeError) errorClass = "RangeError";
	else if (error instanceof Error) errorClass = "Error";
	let cause: SqliteSnapshotFailureCause = "unknown";
	if (isSqliteBusyError(error)) cause = "busy";
	else if (isSqliteIoError(error)) cause = "io";
	else if (isSqliteCorruptError(error)) cause = "corrupt";
	else if (isSqliteCantOpenError(error)) cause = "cant_open";
	else if (sqliteCode !== undefined) cause = "sqlite";
	else if (errno !== undefined) cause = "system";
	else if (error instanceof Error) cause = "error";
	return {
		operation,
		pathStage: resolvedPathStage,
		cause,
		errorClass,
		...(errno === undefined ? {} : { errno }),
		...(sqliteCode === undefined ? {} : { sqliteCode }),
	};
}

// Fallback capture for a live SQLite db that `sqliteVacuumInto` can't read because
// another process holds a lock a second connection never gets past — notably
// Chrome, which opens `Login Data` / `Web Data` with an EXCLUSIVE lock for its
// whole runtime, so VACUUM INTO (a second connection) ALWAYS throws "database is
// locked" and the db would never be captured while the browser is open.
//
// SQLite's locks are advisory POSIX (fcntl) locks: they block another SQLite
// CONNECTION, not a plain byte read — so a raw copy reads the bytes regardless.
// Because that copy is NON-atomic across the main file + sidecars, it only
// accepts a snapshot for which the source main file is BYTE-STABLE across the
// whole copy window (re-read before == after), so the sidecars are guaranteed to
// recover cleanly onto the exact main file captured — never a stale/mismatched
// pair. The copy is then opened READ-WRITE so SQLite recovers it, converted to a
// rollback journal, and verified with `PRAGMA quick_check`.
//
// Named fields (not two positional `string`s) so a swapped call can't type-check —
// a swap would point the destructive `rmSync` at the live source db. Returns true
// when a verified, self-contained db is left at `destPath`; false when it could
// not get a stable, valid copy (the caller skips it and retries next cycle). The
// source is never modified; on failure `destPath` is removed so nothing torn is
// staged.
export function copyLockedSqliteDb(args: {
	readonly srcPath: string;
	readonly destPath: string;
	// Injectable raw read of the source main file, so a test can simulate a
	// concurrent write (differing bytes across the copy window). Defaults to real fs.
	readonly readFile?: (path: string) => Buffer;
	readonly onFailure?: (failure: SqliteSnapshotFailure) => void;
}): boolean {
	const { srcPath, destPath } = args;
	const readFile = args.readFile ?? readFileSync;
	let lastFailure: SqliteSnapshotFailure = {
		operation: "prepare_staged",
		pathStage: "staged_main",
		cause: "unknown",
		errorClass: "unknown",
	};
	for (let attempt = 1; attempt <= LOCKED_DB_COPY_ATTEMPTS; attempt += 1) {
		let verified = false;
		let attemptFailure: SqliteSnapshotFailure | undefined;
		let db: DatabaseSync | undefined;
		let operation: SqliteSnapshotFailureOperation = "prepare_staged";
		let pathStage: SqliteSnapshotPathStage = "staged_main";
		try {
			// Clear any partial output a prior attempt / failed VACUUM INTO left behind.
			// All fs work is INSIDE the try so a copy error (Chrome removed a -wal
			// mid-copy, the source vanished, disk full) yields a clean skip rather than
			// throwing out of the caller's stage loop.
			rmSync(destPath, { force: true });
			pathStage = "staged_sidecars";
			for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
				rmSync(`${destPath}${suffix}`, { force: true });
			}
			operation = "read_source_main";
			pathStage = "source_main";
			const mainBytes = readFile(srcPath);
			operation = "write_staged_main";
			pathStage = "staged_main";
			writeFileSync(destPath, mainBytes);
			operation = "copy_source_sidecars";
			pathStage = "source_and_staged_sidecars";
			for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
				const sidecar = `${srcPath}${suffix}`;
				if (existsSync(sidecar)) copyFileSync(sidecar, `${destPath}${suffix}`);
			}
			// The main file must be unchanged across the copy; otherwise a commit/
			// checkpoint may have run and the sidecars no longer match — retry.
			operation = "verify_source_stability";
			pathStage = "source_main";
			if (!readFile(srcPath).equals(mainBytes)) {
				attemptFailure = {
					operation,
					pathStage,
					cause: "source_changed",
					errorClass: "none",
				};
			} else {
				operation = "open_staged";
				pathStage = "staged_main";
				db = new DatabaseSync(destPath);
				operation = "checkpoint_staged";
				db.exec("PRAGMA wal_checkpoint(TRUNCATE)");
				operation = "set_staged_journal_mode";
				db.exec("PRAGMA journal_mode=DELETE");
				operation = "quick_check_staged";
				const row = db.prepare("PRAGMA quick_check").get() as
					| { readonly quick_check?: string }
					| undefined;
				verified = row?.quick_check === "ok";
				if (!verified) {
					attemptFailure = {
						operation,
						pathStage,
						cause: "quick_check_failed",
						errorClass: "none",
					};
				}
			}
		} catch (error) {
			attemptFailure = classifySqliteSnapshotFailure(error, operation, pathStage);
			verified = false;
		} finally {
			try {
				db?.close();
			} catch (error) {
				verified = false;
				attemptFailure ??= classifySqliteSnapshotFailure(error, "close_staged", "staged_main");
			}
			// The checkpoint made the main file self-contained on success, so the
			// sidecars drop either way; a failed copy is discarded whole.
			for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
				try {
					rmSync(`${destPath}${suffix}`, { force: true });
				} catch (error) {
					verified = false;
					attemptFailure ??= classifySqliteSnapshotFailure(
						error,
						"cleanup_staged",
						"staged_sidecars",
					);
				}
			}
			if (!verified) {
				try {
					rmSync(destPath, { force: true });
				} catch (error) {
					attemptFailure ??= classifySqliteSnapshotFailure(error, "cleanup_staged", "staged_main");
				}
			}
		}
		if (verified && attemptFailure === undefined) return true;
		if (attemptFailure !== undefined) lastFailure = attemptFailure;
	}
	args.onFailure?.(lastFailure);
	return false;
}
