// Off-thread store.db snapshot worker (worker_threads entry point).
//
// node:sqlite is synchronous, so a VACUUM INTO of a multi-GB agent store.db on the
// host thread would freeze the host event loop — and thus the gateway (health checks,
// in-flight turns) — for the entire copy. box-store-sync spawns one of these per
// snapshot so the VACUUM runs on its OWN thread, off the host loop. It writes ONLY
// the destination temp file; the live source db is opened read-only and never
// modified.
//
// MESSAGE-DRIVEN (not one-shot via workerData): the host posts the job, the worker
// runs one VACUUM INTO and posts the result, then STAYS ALIVE (its `message` listener
// keeps the event loop running) until the host terminates it. That ordering matters —
// a worker that self-exited right after posting could have its `exit` event observed
// by the host BEFORE the success `message`, which the host would misread as a failure,
// drop the completed snapshot, and latch the worker off.
//
// Emitted as CJS (box-store-vacuum-worker.cjs) with the same NODE_PATH banner as the
// agent isolation worker (scripts/build-main.mjs) and copied into the shipped host
// bundle (box/build/build-sand-host-bundle.sh), so it resolves the externalized node:sqlite
// the same way when spawned by the host (ELECTRON_RUN_AS_NODE).

import { parentPort } from "node:worker_threads";

import { invariant } from "../../../shared/invariant.js";
import { sqliteVacuumInto } from "./sqlite-snapshot.js";

interface VacuumJob {
	readonly srcPath: string;
	readonly destPath: string;
	readonly busyTimeoutMs: number;
}

const port = parentPort;
invariant(port != null, "box-store-vacuum-worker must run as a worker_thread");

port.on("message", (job: VacuumJob) => {
	try {
		sqliteVacuumInto(job.srcPath, job.destPath, job.busyTimeoutMs);
		port.postMessage({ ok: true });
	} catch (error) {
		// The VACUUM ran and failed (unreadable db, disk full, …). Report it so the host
		// fails closed for this agent rather than retrying in-process.
		port.postMessage({
			ok: false,
			message: error instanceof Error ? error.message : String(error),
		});
	}
});
